out.append('function slugify(value) { return String(value).normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }\n')
out.append('')
out.append('function inferType(word) {\n  const id=slugify(word);\n  if (TYPE_HINTS.feminine.has(id)) return "substantivo feminino";\n  if (/mente$/.test(id)) return "advérbio";\n  if (/ar$|er$|ir$/.test(id) && !id.includes(" ")) return "verbo";\n  return "substantivo";\n}\n')
