out.append('function buildDefinition(word, category) {\n  const clean = word.replace(/^experiência de |^sensação de |^memória de |^medo de |^desejo de |^ausência de |^presença de |^expectativa de |^ritual de |^momento de |^estado de |^gesto de |^ato de |^vontade de |^necessidade de /i, "");\n  const map = {\n    "Sentimentos": `Um estado afetivo que colore a forma como percebemos pessoas, acontecimentos ou a nós mesmos. Em “${clean}”, o importante é a experiência, não apenas sua intensidade.`,\n    "Amor & atração": `Uma forma de vínculo, desejo ou aproximação entre pessoas. “${clean}” descreve aqui o movimento afetivo que torna uma relação mais intensa, mais próxima ou mais significativa.`,\n    "Relações humanas": `Uma dinâmica de convivência entre pessoas, marcada por expectativas, gestos, limites e reciprocidades. “${clean}” aparece quando a relação produz esse tipo particular de troca.`,\n    "Mente": `Um movimento ou estado do pensamento: algo que organiza, interrompe, amplia ou desloca a atenção. “${clean}” nomeia uma maneira específica de a experiência mental acontecer.`,\n    "Sensações": `Uma experiência percebida no corpo ou pelos sentidos. “${clean}” ganha importância quando a pessoa percebe uma qualidade concreta de presença, desconforto, textura ou ritmo.`,\n    "Tempo & memória": `Uma maneira de experimentar passagem, duração, lembrança ou retorno. “${clean}” liga um momento ao modo como ele continua — ou deixa de continuar — dentro de nós.`,\n    "Experiências": `Um acontecimento ou situação reconhecível da vida cotidiana. “${clean}” interessa menos pelo tamanho do evento e mais pelo tipo de experiência que ele produz.`,\n    "Palavras raras": `Termo de uso menos frequente no português contemporâneo, preservado neste projeto por sua precisão, sonoridade ou valor histórico. “${clean}” descreve uma ideia que merece ser reencontrada.`,\n    "Identidade & pertencimento": `Um aspecto de como uma pessoa se reconhece, é reconhecida ou encontra lugar entre outras pessoas e espaços. “${clean}” ajuda a nomear essa relação entre eu, origem e pertencimento.`,\n    "Comportamentos": `Uma forma de agir, responder ou repetir determinada ação. “${clean}” descreve um padrão que pode aparecer de modo automático, aprendido ou deliberado.`,\n    "Pensamentos": `Uma forma particular de organizar ideias, imagens, dúvidas ou conclusões. “${clean}” descreve o modo como a mente recorta e interpreta aquilo que acontece.`,\n    "Conceitos difíceis": `Um conceito usado para apontar uma experiência que costuma escapar de explicações simples. “${clean}” fica mais claro quando observado em situações concretas e contraditórias.`,\n    "Lugar & atmosfera": `Uma qualidade de espaço, ambiente ou paisagem que muda a maneira como um lugar é percebido. “${clean}” descreve aquilo que se sente além de simplesmente localizar um ponto no mapa.`,\n    "Leitura & linguagem": `Uma unidade, recurso ou fenômeno da linguagem que altera o sentido, o ritmo ou a relação entre palavras. “${clean}” importa pelo que permite dizer — e pelo que deixa implícito.`,\n    "Vida cotidiana": `Uma pequena ação, situação ou rotina que parece banal até ser observada de perto. “${clean}” nomeia uma dessas unidades discretas que formam um dia inteiro.`,\n    "Filosofia da vida": `Uma ideia para pensar a condição humana, nossas escolhas e a maneira como habitamos o mundo. “${clean}” funciona menos como resposta pronta e mais como ferramenta de reflexão.`,\n    "Afetos sociais": `Um estado afetivo que nasce, muda ou se revela na presença de outras pessoas. “${clean}” ajuda a perceber como o olhar, a aprovação, a distância ou o cuidado do outro nos afetam.`\n  };\n  return map[category] || `Um conceito útil para nomear uma experiência humana específica: “${clean}” ganha sentido quando relacionado ao contexto em que aparece.`;\n}\n\n')
out.append('function buildRecognition(word, category) {\n  const clean=word.replace(/^experiência de |^sensação de |^memória de |^medo de |^desejo de |^ausência de |^presença de |^expectativa de |^ritual de |^momento de |^estado de |^gesto de |^ato de |^vontade de |^necessidade de /i, "");\n  const openers={\n    "Sentimentos":"Você percebe isso quando a emoção não é apenas um rótulo, mas muda o jeito de notar o que está diante de você.",\n    "Amor & atração":"Costuma aparecer em pequenos gestos de aproximação: no que você espera, procura, evita ou deseja prolongar.",\n    "Relações humanas":"É reconhecível na maneira como duas ou mais pessoas ajustam distância, confiança, expectativa ou limite.",\n    "Mente":"Fica mais evidente quando você observa não só o que pensa, mas o caminho que levou até esse pensamento.",\n    "Sensações":"É uma daquelas experiências que o corpo percebe alguns segundos antes de a linguagem conseguir descrevê-la.",\n    "Tempo & memória":"Geralmente surge quando um momento do presente encosta em alguma coisa que veio antes ou ainda parece estar por vir.",\n    "Experiências":"Pode ser notado em uma cena comum que, por algum motivo, adquire um peso ou uma textura incomum.",\n    "Palavras raras":"Você pode reconhecer o conceito em textos, conversas ou situações precisas nas quais uma palavra mais comum parece insuficiente.",\n    "Identidade & pertencimento":"Torna-se perceptível quando a pergunta deixa de ser “o que eu faço?” e passa a ser “onde isso me coloca?”.",\n    "Comportamentos":"Aparece melhor quando você olha para a repetição: o que faz de novo, mesmo quando prometeu agir diferente.",\n    "Pensamentos":"Você pode percebê-lo no intervalo entre um estímulo e a conclusão que sua mente produz a partir dele.",\n    "Conceitos difíceis":"Normalmente aparece em situações onde duas descrições parecem verdadeiras ao mesmo tempo, mas nenhuma conta a história inteira.",\n    "Lugar & atmosfera":"Fica claro quando duas paisagens parecidas provocam respostas completamente diferentes em você.",\n    "Leitura & linguagem":"Surge quando uma mesma frase muda de efeito por causa do contexto, do tom ou do que ficou sem ser dito.",\n    "Vida cotidiana":"Você encontra isso nos detalhes: na tarefa repetida, no pequeno atraso, no conforto inesperado ou no incômodo banal.",\n    "Filosofia da vida":"Pode ser observado quando uma experiência concreta abre uma pergunta maior sobre como viver, escolher ou conviver.",\n    "Afetos sociais":"Aparece quando o comportamento ou a presença de outra pessoa altera sua segurança, autoestima, proximidade ou vontade de participar."\n  };\n  return `${openers[category] || "Observe quando esse conceito começa a descrever melhor a situação do que uma palavra genérica."} Muitas vezes, ${clean.toLowerCase()} aparece antes de encontrarmos um nome para isso.`;\n}\n')
out.append('')
out.append('function buildEntries() {\n  const entries=[];\n  const used=new Set();\n  CATEGORY_ORDER.forEach((category, ci)=>{\n    const words=CATEGORY_CATALOGS[category];\n    words.forEach((word, wi)=>{\n      const base=slugify(word);\n      let id=base || `termo-${ci}-${wi}`;\n      if (used.has(id)) id=`${base}-${ci+1}`;\n      used.add(id);\n      const related=[];\n      if (wi>0) related.push(slugify(words[wi-1]));\n      if (wi+1<words.length) related.push(slugify(words[wi+1]));\n      if (wi+7<words.length) related.push(slugify(words[wi+7]));\n      if (ci>0) related.push(slugify(CATEGORY_CATALOGS[CATEGORY_ORDER[ci-1]][wi % 200]));\n      const uniqueRelated=[...new Set(related)].filter(x=>x!==id).slice(0,4);\n      const contrasts = wi+3<words.length ? [slugify(words[wi+3])] : [];\n      const termForeign=/\\b(kairos|déjà-vu|jamais vu|reframing|crush|ethos|pathos|logos|mimesis|episteme|eudaimonia|ataraxia|teleologia|práxis|per se)\\b/i.test(word);\n      entries.push({id,word,type:inferType(word),category,categoryIndex:ci,definition:buildDefinition(word,category),related:uniqueRelated,contrasts:contrasts.filter(Boolean),recognition:buildRecognition(word,category),termKind:termForeign?"termo estrangeiro ou contemporâneo":"termo do português",addedIndex:(ci*200)+wi});\n    });\n  });\n  // Hand-written polish for the showcase entries.\n  const polish={\n    saudade:{type:"substantivo feminino",definition:"Sentimento de falta que nasce quando uma pessoa, lugar, tempo ou possibilidade continua tendo presença emocional mesmo estando ausente. Não é apenas querer de volta; pode ser também conviver com aquilo que já não pode voltar da mesma forma.",recognition:"Ela costuma aparecer quando algo cotidiano — uma música, uma rua, um cheiro, um horário — devolve por alguns segundos uma presença que não está mais ali.",related:["nostalgia","ausencia","lembranca","anseio"],contrasts:["presenca","novidade"]},\n    nostalgia:{type:"substantivo feminino",definition:"Afeição melancólica por um tempo passado, especialmente quando lembramos dele como um lugar ao qual gostaríamos de retornar. A nostalgia não recupera o passado; ela o reorganiza dentro do presente.",recognition:"Surge quando uma fotografia, uma canção ou um objeto antigo faz um período inteiro parecer mais próximo do que ele realmente está.",related:["saudade","memoria","infancia","efemeridade"],contrasts:["novidade","presenca"]},\n    efemeridade:{type:"substantivo feminino",definition:"Qualidade daquilo que dura pouco ou está sempre passando. A efemeridade chama atenção para a curta permanência das coisas, inclusive das que parecem estáveis enquanto acontecem.",recognition:"Você a percebe quando tenta prolongar uma conversa, um verão, uma fase ou uma sensação e nota que ela já mudou enquanto você ainda estava dentro dela.",related:["transitoriedade","impermanencia","tempo","passagem"],contrasts:["permanencia","continuidade"]},\n    ambivalencia:{type:"substantivo feminino",definition:"Coexistência de sentimentos, desejos ou avaliações que puxam em direções diferentes diante da mesma coisa. A ambivalência não significa falta de opinião; significa ter mais de uma resposta verdadeira ao mesmo tempo.",recognition:"Você a reconhece quando quer se aproximar e se afastar, aceitar e recusar, permanecer e ir embora — sem que nenhuma dessas vontades pareça falsa.",related:["contradicao","hesitacao","nuance","incerteza"],contrasts:["conviccao","clareza"]},\n    pertencimento:{type:"substantivo masculino",definition:"Sensação de ter lugar entre pessoas, espaços, histórias ou práticas que reconhecemos como nossas. Pode ser dado, construído, herdado ou conquistado aos poucos.",recognition:"Aparece quando você deixa de observar um ambiente como visitante e começa a sentir que sua presença ali faz sentido para você e para os outros.",related:["identidade","comunidade","acolhimento","familiaridade"],contrasts:["exclusao","estranhamento"]},\n    epifania:{type:"substantivo feminino",definition:"Compreensão súbita que reorganiza um problema, uma lembrança ou uma percepção. O conteúdo pode ser simples; o efeito está na mudança de perspectiva que ele provoca.",recognition:"É aquele momento em que uma conexão que parecia escondida fica óbvia de repente e você se pergunta como não havia percebido antes.",related:["insight","compreensao","perplexidade","contemplacao"],contrasts:["confusao","desconhecimento"]},\n    ressonancia:{type:"substantivo feminino",definition:"Efeito de algo continuar vibrando dentro de nós depois do contato inicial. Uma frase, uma obra, uma lembrança ou uma experiência pode ter ressonância sem permanecer literalmente presente.",recognition:"Acontece quando você termina uma conversa ou sai de um lugar, mas um detalhe continua reaparecendo no pensamento muito depois.",related:["eco","memoria","presenca","afinidade"],contrasts:["indiferenca","apagamento"]},\n    quietude:{type:"substantivo feminino",definition:"Estado de pouca agitação, física ou mental. Quietude não é necessariamente silêncio absoluto: pode existir enquanto o mundo continua acontecendo ao redor.",recognition:"Você a percebe quando o ritmo das coisas desacelera o suficiente para que pequenos sons, pensamentos ou movimentos voltem a ficar perceptíveis.",related:["serenidade","silencio","contemplacao","calma"],contrasts:["agitacao","pressa"]},\n    vulnerabilidade:{type:"substantivo feminino",definition:"Condição de estar exposto à possibilidade de sofrer dano, rejeição ou perda, seja física, emocional ou socialmente. Também pode ser o estado que torna possível uma relação mais honesta.",recognition:"Ela aparece quando esconder-se parece mais seguro, mas você decide mostrar algo que realmente importa e aceita não controlar a resposta do outro.",related:["intimidade","confianca","medo","abertura"],contrasts:["defensividade","autoprotecao"]},\n  };\n  entries.forEach(e=>{ if(polish[e.id]) Object.assign(e,polish[e.id]); });\n  return entries;\n}\n\nconst DICTIONARY = buildEntries();\nconst ENTRY_MAP = new Map(DICTIONARY.map(e=>[e.id,e]));\n\nif (typeof window !== "undefined") { window.DICTIONARY = DICTIONARY; window.ENTRY_MAP=ENTRY_MAP; window.CATEGORY_CATALOGS=CATEGORY_CATALOGS; window.CATEGORY_META=CATEGORY_META; window.CATEGORY_ORDER=CATEGORY_ORDER; window.CATEGORY_COLORS=CATEGORY_COLORS; }\n')
Path('/mnt/data/dicionario/data.js').write_text('\n'.join(out), encoding='utf-8')
